CREATE POLICY "Partners upload own service files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'service-partner-files' AND (storage.foldername(name))[1] = public.current_service_partner_id()::text);
CREATE POLICY "Partners read own service files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'service-partner-files' AND ((storage.foldername(name))[1] = public.current_service_partner_id()::text OR public.is_staff(auth.uid())));
CREATE POLICY "Partners update own service files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'service-partner-files' AND (storage.foldername(name))[1] = public.current_service_partner_id()::text) WITH CHECK (bucket_id = 'service-partner-files' AND (storage.foldername(name))[1] = public.current_service_partner_id()::text);
CREATE POLICY "Staff manage service files" ON storage.objects FOR ALL TO authenticated USING (bucket_id = 'service-partner-files' AND public.is_staff(auth.uid())) WITH CHECK (bucket_id = 'service-partner-files' AND public.is_staff(auth.uid()));